:root {
  /* Colors */
  --color-linen-canvas: #fefffc;
  --color-paper: #ffffff;
  --color-frosted-pane: #ffffffd9;
  --color-fog-field: #f9faf7;
  --color-onyx-ink: #1f1f29;
  --color-charcoal-ink: #2c2c2c;
  --color-graphite-nav: #444141;
  --color-pewter-caption: #646464;
  --color-mist-label: #9db0bd;
  --color-stone-border: #cfd1d3;
  --color-steel-chip: #9cb4c024;
  --color-signal-cerulean: #0081c0;
  --color-lagoon-ring: #41a1cf;

  /* Typography — Font Families */
  --font-pp-mondwest: "PP Mondwest", "Newsreader Display", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-af: "Af", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-caption: 13px;
  --leading-caption: 1.4;
  --tracking-caption: -0.13px;
  --text-body: 15px;
  --leading-body: 1.4;
  --tracking-body: -0.15px;
  --text-subheading: 18px;
  --leading-subheading: 1.3;
  --tracking-subheading: -0.18px;
  --text-heading-sm: 27px;
  --leading-heading-sm: 1.5;
  --tracking-heading-sm: -1.08px;
  --text-heading: 40px;
  --leading-heading: 1.1;
  --tracking-heading: -0.8px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: -0.96px;
  --text-display: 54px;
  --leading-display: 1.1;
  --tracking-display: -1.08px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;
  --spacing-140: 140px;
  --spacing-220: 220px;

  /* Layout */
  --page-max-width: 1080px;
  --section-gap: 120px;
  --card-padding: 24px;
  --element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-3xl: 27px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 4px;
  --radius-buttons: 8px;
  --radius-inner-tiles: 8px;
  --radius-alert-banners: 8px;
  --radius-nav: 12px;
  --radius-cards: 16px;
  --radius-sections: 24px;
  --radius-pills: 27px;
  --radius-avatars: 9999px;
  --radius-inputs: 0px;
  --radius-images: 0px;

  /* Shadows */
  --shadow-subtle: 0px 1px 1px 0px rgba(0, 0, 0, 0.04);
  --shadow-subtle-2: 0px 0px 0px 1px rgb(222, 226, 222);
  --shadow-sm: 0px 2px 4px 0px rgba(80, 115, 138, 0.24);
  --shadow-sm-2: 0px 1px 8px 0px rgba(0, 0, 0, 0.05);
  --shadow-md: 0px 2px 6px 0px rgba(0, 0, 0, 0.15);
  --shadow-lg: 0px 1px 1px 0px rgba(0, 0, 0, 0.08), 0px 4px 5px 0px rgba(0, 0, 0, 0.08);
  --shadow-xl: 0px 2px 2px 0px rgba(0, 0, 0, 0.06), 0px 0px 0px 5px rgba(0, 0, 0, 0.04);

  /* Surfaces */
  --surface-linen-canvas: #fefffc;
  --surface-fog-field: #f9faf7;
  --surface-paper: #ffffff;
  --surface-frosted-pane: #ffffffd9;
  --surface-onyx-ink: #1f1f29;
}

